import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { PRODUCTION_BASE_PATH } from "@/lib/basePath.mjs";
import { dotsPath, layoutDots } from "@/lib/world/dotMatrix";
import { STILLS } from "@/lib/world/stills";

const PUBLIC = join(__dirname, "../../public");
const html = readFileSync(join(PUBLIC, "404.html"), "utf8");
const DOT = 2 / 3;

/** public/404.html is generated by scripts/generate-404.mjs; these fail if it drifts from the site. Run `npm run not-found`. */
describe("the static 404 page", () => {
  it("draws the wordmark and the 404 with the site's own dot-matrix glyphs", () => {
    const logo = layoutDots("RESTOBOOM.");
    expect(html).toContain(dotsPath(logo.dots.filter((d) => d.char !== "."), DOT, 0));
    expect(html).toContain(dotsPath(logo.dots.filter((d) => d.char === "."), DOT, 0));
    expect(html).toContain(dotsPath(layoutDots("404").dots, DOT, 0));
  });

  it("uses the lost still as its backdrop, with the upright one on phones", () => {
    expect(html).toContain(`src="${PRODUCTION_BASE_PATH}${STILLS.lost.src}"`);
    expect(html).toContain(`srcset="${PRODUCTION_BASE_PATH}${STILLS.lost.phone?.src}"`);
  });

  it("only links and loads files that exist, under the production path", () => {
    const urls = [...html.matchAll(/(?:href|src|srcset)="([^"]+)"|url\((\/[^)]+)\)/g)].map((m) => m[1] ?? m[2]);
    expect(urls.length).toBeGreaterThan(8);
    for (const url of urls) {
      expect(url.startsWith(`${PRODUCTION_BASE_PATH}/`), url).toBe(true);
      const path = url.slice(PRODUCTION_BASE_PATH.length);
      if (!path.endsWith("/")) expect(existsSync(join(PUBLIC, path)), path).toBe(true);
    }
  });

  it("keeps the bilingual message, the way home and noindex", () => {
    expect(html).toContain('<html lang="fr-CA">');
    expect(html).toContain('<meta name="robots" content="noindex" />');
    expect(html).toContain("<h1>Cette page a changé d'adresse.</h1>");
    expect(html).toContain('<span lang="en">This page doesn\'t exist (anymore).</span>');
    expect(html).toContain(`href="${PRODUCTION_BASE_PATH}/">Retour à l'accueil`);
  });
});
